let text = '';

if (typeof msg.payload === 'string') {
    text = msg.payload;
} else if (msg.payload && msg.payload.choices && msg.payload.choices[0] && msg.payload.choices[0].message && typeof msg.payload.choices[0].message.content === 'string') {
    text = msg.payload.choices[0].message.content;
} else {
    text = JSON.stringify(msg.payload, null, 2);
}

msg.onInitSubmission = {
    textArea: text
};

return msg;

